INSERT INTO reviews (id, title, year, rating, genres, poster, body, created_at, updated_at) VALUES
  ('sample-dust-sheriff', '먼지의 보안관', 2025, 4, ARRAY['서부', '액션']::text[], '/seed/dust-sheriff-poster.svg', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"철도가 비껴간 뒤 몰락한 마을에 은퇴를 앞둔 보안관이 남아 있다. 영화는 총잡이의 전설을 되살리는 대신 아무도 찾지 않는 땅을 지키는 일의 쓸쓸함에서 출발한다."}]},{"type":"image","attrs":{"src":"/seed/dust-sheriff-scene.svg","alt":"붉은 흙먼지가 이는 황량한 마을 거리"}},{"type":"paragraph","content":[{"type":"text","text":"결투 장면은 놀랄 만큼 짧다. 긴 기다림 끝에 총성이 단 두 번 울리고, 카메라는 쓰러진 사람보다 그것을 지켜본 마을 사람들의 얼굴에 더 오래 머문다."}]},{"type":"image","attrs":{"src":"/seed/dust-sheriff-scene-2.svg","alt":"해 질 녘 언덕 위에 선 말과 기수의 그림자"}},{"type":"paragraph","content":[{"type":"text","text":"주연 배우의 주름진 얼굴이 넓은 화면을 혼자 채운다. 말수가 적은 인물인데도 지친 어깨와 느린 걸음만으로 평생의 후회를 전달한다."}]},{"type":"paragraph","content":[{"type":"text","text":"후반에 등장하는 악당이 다소 전형적인 것은 흠이다. 하지만 장르의 관습을 존중하면서 거기에 나이 듦이라는 주제를 얹어 낸 솜씨는 충분히 칭찬할 만하다."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"이 글은 포트폴리오를 위해 지어낸 가상의 영화 리뷰입니다."}]}]}'::jsonb, '2026-07-08T09:00:00.000Z', '2026-07-08T09:00:00.000Z'),
  ('sample-last-cartographer', '마지막 지도 제작자', 2024, 5, ARRAY['모험', '드라마']::text[], '/seed/last-cartographer-poster.svg', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"위성 지도가 세상을 뒤덮은 시대에 손으로 지도를 그리는 노인이 마지막 미측량 지역으로 떠난다. 줄거리만 들으면 낭만적인 모험담 같지만, 영화는 곧 그 낭만의 값을 묻기 시작한다."}]},{"type":"image","attrs":{"src":"/seed/last-cartographer-scene.svg","alt":"안개 낀 협곡을 내려다보는 절벽 위의 측량 도구"}},{"type":"paragraph","content":[{"type":"text","text":"길을 안내하는 현지 청년의 시선이 들어오면서 이야기가 깊어진다. 누군가에게 빈칸이었던 땅이 다른 누군가에게는 평생 살아온 집이었다는 사실을 영화는 조심스럽게 드러낸다."}]},{"type":"image","attrs":{"src":"/seed/last-cartographer-scene-2.svg","alt":"정글 강을 거슬러 오르는 작은 나무배"}},{"type":"paragraph","content":[{"type":"text","text":"강을 거슬러 오르는 긴 여정 내내 촬영은 풍경을 구경거리로 만들지 않는다. 벌레 소리와 젖은 옷, 부르튼 발이 먼저 보이고 그다음에야 장엄한 협곡이 나타난다."}]},{"type":"image","attrs":{"src":"/seed/last-cartographer-scene-3.svg","alt":"손으로 그린 지도 위에 놓인 낡은 나침반"}},{"type":"paragraph","content":[{"type":"text","text":"노인이 완성한 지도를 어떻게 하는지 보여 주는 결말은 올해 본 어떤 반전보다 강렬하다. 무엇을 기록하고 무엇을 남겨 둘 것인가에 대한 질문이 극장을 나선 뒤에도 따라온다."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"이 글은 포트폴리오를 위해 지어낸 가상의 영화 리뷰입니다."}]}]}'::jsonb, '2026-07-01T09:00:00.000Z', '2026-07-01T09:00:00.000Z'),
  ('sample-island-of-clocks', '시계의 섬', 2026, 4, ARRAY['모험', '판타지', '가족']::text[], '/seed/island-of-clocks-poster.svg', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"할아버지의 고장 난 회중시계를 고치러 떠난 남매가 시간이 구역마다 다르게 흐르는 섬에 닿는다. 아이들의 눈높이에 맞춘 설정이지만 규칙이 명확해서 어른도 함께 추리하는 재미가 있다."}]},{"type":"image","attrs":{"src":"/seed/island-of-clocks-scene.svg","alt":"거대한 톱니바퀴가 돌아가는 섬의 해안"}},{"type":"paragraph","content":[{"type":"text","text":"구역을 넘을 때마다 계절과 나이가 바뀌는 시각 효과가 볼거리다. 특히 남매가 잠시 어른이 되어 서로를 낯설어하는 장면은 이 영화의 가장 빛나는 순간이다."}]},{"type":"image","attrs":{"src":"/seed/island-of-clocks-scene-2.svg","alt":"수많은 시계탑이 솟은 마을의 저녁 풍경"}},{"type":"paragraph","content":[{"type":"text","text":"중간에 등장하는 시계공 캐릭터의 분량이 많아 전개가 잠시 느려진다. 그래도 그가 들려주는 잃어버린 시간의 이야기는 이후의 결말을 위한 충분한 밑거름이 된다."}]},{"type":"paragraph","content":[{"type":"text","text":"모험 끝에 얻는 교훈이 다소 직설적이긴 해도 불쾌하지 않다. 가족이 함께 극장을 찾기에 더없이 알맞은 작품이다."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"이 글은 포트폴리오를 위해 지어낸 가상의 영화 리뷰입니다."}]}]}'::jsonb, '2026-06-24T09:00:00.000Z', '2026-06-24T09:00:00.000Z'),
  ('sample-fourth-witness', '네 번째 증인', 2025, 5, ARRAY['범죄', '미스터리']::text[], '/seed/fourth-witness-poster.svg', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"한 건의 살인 사건을 세 증인의 진술로 재구성한 뒤, 존재하지 않았던 네 번째 증인이 나타나며 모든 것이 흔들린다. 같은 장면을 조금씩 다르게 보여 주는 구조가 놀라울 만큼 정교하다."}]},{"type":"image","attrs":{"src":"/seed/fourth-witness-scene.svg","alt":"어두운 법정 증인석에 떨어지는 한 줄기 빛"}},{"type":"paragraph","content":[{"type":"text","text":"각 진술마다 색감과 카메라의 높이가 미묘하게 달라진다. 무심코 지나친 그 차이가 나중에 결정적인 단서였음을 깨닫는 순간, 다시 보고 싶어진다."}]},{"type":"image","attrs":{"src":"/seed/fourth-witness-scene-2.svg","alt":"비 내리는 창가에 붙은 수사 메모"}},{"type":"paragraph","content":[{"type":"text","text":"검사와 변호사의 대결보다 흥미로운 것은 진실을 대하는 태도의 차이다. 영화는 누가 범인인지보다 사람들이 왜 자신이 본 것을 믿고 싶어 하는지에 더 관심을 둔다."}]},{"type":"paragraph","content":[{"type":"text","text":"끝내 모든 것을 설명하지 않는 결말이 불만스러운 관객도 있을 것이다. 그러나 관람 후 나누게 될 긴 대화까지 영화의 일부라고 생각하면 이보다 알맞은 마무리는 없다."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"이 글은 포트폴리오를 위해 지어낸 가상의 영화 리뷰입니다."}]}]}'::jsonb, '2026-06-17T09:00:00.000Z', '2026-06-17T09:00:00.000Z'),
  ('sample-pawnshop-ledger', '전당포 장부', 2023, 3, ARRAY['범죄', '드라마']::text[], '/seed/pawnshop-ledger-poster.svg', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"폐업을 앞둔 전당포의 장부에 지역 유지들의 비밀이 적혀 있다는 설정은 꽤 흥미롭다. 물건 하나하나에 얽힌 사연을 풀어내는 초반은 잘 쓴 단편집처럼 읽힌다."}]},{"type":"image","attrs":{"src":"/seed/pawnshop-ledger-scene.svg","alt":"어두운 전당포 진열장에 놓인 손목시계들"}},{"type":"paragraph","content":[{"type":"text","text":"문제는 조직 폭력배가 끼어드는 중반 이후다. 작고 내밀했던 이야기가 익숙한 복수극으로 바뀌면서 앞서 쌓은 인물의 결이 대부분 지워진다."}]},{"type":"image","attrs":{"src":"/seed/pawnshop-ledger-scene-2.svg","alt":"가게 카운터 위에 펼쳐진 낡은 장부"}},{"type":"paragraph","content":[{"type":"text","text":"전당포 주인을 연기한 배우만은 끝까지 흔들림이 없다. 손님의 시계를 살피는 짧은 시선만으로 그 사람의 형편을 꿰뚫어 보는 장면은 오래 기억에 남는다."}]},{"type":"paragraph","content":[{"type":"text","text":"범죄물보다 동네의 기록으로 밀고 나갔다면 더 좋았을 영화다. 아쉬움이 크지만 앞부분 사십 분만으로도 볼 가치는 있다."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"이 글은 포트폴리오를 위해 지어낸 가상의 영화 리뷰입니다."}]}]}'::jsonb, '2026-06-10T09:00:00.000Z', '2026-06-10T09:00:00.000Z'),
  ('sample-grandma-submarine', '할머니의 잠수함', 2026, 4, ARRAY['가족', '코미디']::text[], '/seed/grandma-submarine-poster.svg', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"칠순의 할머니가 뒷마당에서 잠수함을 만들어 손자와 함께 바다로 나선다. 황당한 전제를 끝까지 진지한 얼굴로 밀어붙이는 태도가 이 코미디의 가장 큰 힘이다."}]},{"type":"image","attrs":{"src":"/seed/grandma-submarine-scene.svg","alt":"마당 한가운데 놓인 노란 수제 잠수함"}},{"type":"paragraph","content":[{"type":"text","text":"동네 공무원과 해양 경찰이 뒤를 쫓는 소동은 어린 관객이 깔깔거리기에 충분하다. 어른 관객은 그 틈틈이 놓인 할머니의 지나온 삶을 알아채고 조금 다른 웃음을 짓게 된다."}]},{"type":"image","attrs":{"src":"/seed/grandma-submarine-scene-2.svg","alt":"둥근 창밖으로 보이는 푸른 바닷속 물고기 떼"}},{"type":"paragraph","content":[{"type":"text","text":"바닷속 장면은 예산의 한계가 보이지만 오히려 손으로 만든 듯한 질감이 작품과 잘 어울린다. 수제 잠수함이라는 설정과 영화의 만듦새가 묘하게 맞아떨어진다."}]},{"type":"paragraph","content":[{"type":"text","text":"할머니가 왜 바다로 가려 했는지 밝혀지는 대목에서 객석 곳곳이 조용해진다. 웃기고 시작해 뭉클하게 끝내는 가족 영화의 정석에 가깝다."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"이 글은 포트폴리오를 위해 지어낸 가상의 영화 리뷰입니다."}]}]}'::jsonb, '2026-06-03T09:00:00.000Z', '2026-06-03T09:00:00.000Z'),
  ('sample-moving-day', '이삿날의 식탁', 2024, 4, ARRAY['가족', '드라마']::text[], '/seed/moving-day-poster.svg', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"삼십 년 산 집을 떠나는 날 하루를 다룬다. 다 큰 삼 남매가 짐을 싸러 모이고, 상자가 하나 닫힐 때마다 묵은 서운함이 하나씩 꺼내진다."}]},{"type":"image","attrs":{"src":"/seed/moving-day-scene.svg","alt":"상자가 쌓인 거실 한가운데 남은 나무 식탁"}},{"type":"paragraph","content":[{"type":"text","text":"사건이랄 것은 없지만 대화의 호흡이 좋아 지루할 틈이 없다. 같은 일을 서로 다르게 기억하는 남매의 말다툼은 어느 집에나 있을 법해서 웃다가 곧 민망해진다."}]},{"type":"image","attrs":{"src":"/seed/moving-day-scene-2.svg","alt":"텅 빈 방 바닥에 비친 오후의 긴 햇빛"}},{"type":"paragraph","content":[{"type":"text","text":"어머니 역의 배우는 거의 말을 하지 않고 식탁을 닦는다. 아무도 쓰지 않을 식탁을 끝까지 닦는 그 동작이 영화의 모든 대사보다 많은 것을 말한다."}]},{"type":"paragraph","content":[{"type":"text","text":"이사 트럭이 떠난 뒤 빈집을 오래 비추는 마지막 숏은 다소 길다. 그러나 그 시간 동안 관객은 저마다 자기 집의 식탁을 떠올리게 된다."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"이 글은 포트폴리오를 위해 지어낸 가상의 영화 리뷰입니다."}]}]}'::jsonb, '2026-05-27T09:00:00.000Z', '2026-05-27T09:00:00.000Z'),
  ('sample-fog-kingdom', '안개 왕국의 서기', 2025, 3, ARRAY['판타지', '모험']::text[], '/seed/fog-kingdom-poster.svg', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"왕의 말을 기록하는 말단 서기가 왕국의 역사가 조작되었음을 알게 된다. 칼과 마법 대신 문서와 기록을 전면에 내세운 설정은 근래 판타지에서 보기 드물게 신선하다."}]},{"type":"image","attrs":{"src":"/seed/fog-kingdom-scene.svg","alt":"안개 위로 첨탑만 드러난 왕국의 성"}},{"type":"paragraph","content":[{"type":"text","text":"서고 내부를 구현한 미술은 탄성을 자아낸다. 층층이 쌓인 두루마리 사이로 사다리가 뻗어 나간 공간은 그 자체로 이 세계의 역사를 말해 준다."}]},{"type":"image","attrs":{"src":"/seed/fog-kingdom-scene-2.svg","alt":"두루마리가 빼곡히 들어찬 왕실 서고"}},{"type":"paragraph","content":[{"type":"text","text":"다만 주인공이 서고를 떠나 모험에 나서면서 영화는 평범해진다. 독창적이던 세계가 흔한 예언과 추격으로 채워지는 후반은 초반의 기대를 채워 주지 못한다."}]},{"type":"paragraph","content":[{"type":"text","text":"후속편을 염두에 둔 듯한 결말도 김을 뺀다. 그럼에도 전반부의 상상력만큼은 다음 작품을 기대하게 만든다."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"이 글은 포트폴리오를 위해 지어낸 가상의 영화 리뷰입니다."}]}]}'::jsonb, '2026-05-20T09:00:00.000Z', '2026-05-20T09:00:00.000Z'),
  ('sample-moon-weaver', '달을 짜는 사람', 2023, 4, ARRAY['판타지', '로맨스']::text[], '/seed/moon-weaver-poster.svg', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"밤마다 달빛으로 천을 짜는 직녀와 그 천을 팔러 다니는 행상의 이야기다. 설화처럼 단순한 줄거리를 택한 대신 영화는 모든 힘을 빛과 질감을 그리는 데 쏟았다."}]},{"type":"image","attrs":{"src":"/seed/moon-weaver-scene.svg","alt":"은빛 실이 드리운 밤하늘 아래의 베틀"}},{"type":"paragraph","content":[{"type":"text","text":"실제 천과 조명만으로 만들었다는 달빛 장면은 컴퓨터 그래픽이 줄 수 없는 온기를 품고 있다. 천 한 폭이 바람에 일렁이는 순간 극장 안의 공기까지 달라지는 듯하다."}]},{"type":"image","attrs":{"src":"/seed/moon-weaver-scene-2.svg","alt":"달빛에 젖은 갈대밭을 걷는 두 사람"}},{"type":"paragraph","content":[{"type":"text","text":"두 사람의 사랑은 말수가 적다. 서로의 손에 난 상처를 알아보는 정도의 몸짓으로 관계가 깊어지는데, 그 절제가 오히려 긴 여운을 남긴다."}]},{"type":"paragraph","content":[{"type":"text","text":"이야기가 단조롭다는 평도 나올 법하다. 그러나 이 영화는 줄거리를 따라가기보다 한 편의 긴 시처럼 머물며 볼 때 진가를 드러낸다."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"이 글은 포트폴리오를 위해 지어낸 가상의 영화 리뷰입니다."}]}]}'::jsonb, '2026-05-13T09:00:00.000Z', '2026-05-13T09:00:00.000Z'),
  ('sample-court-archivist', '사관의 붓', 2026, 5, ARRAY['역사', '드라마']::text[], '/seed/court-archivist-poster.svg', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"왕의 곁에서 모든 것을 기록해야 하는 젊은 사관이 왕의 치부를 목격한다. 대규모 전투 하나 없는 사극이지만 붓을 드느냐 마느냐의 선택이 어떤 칼부림보다 팽팽하다."}]},{"type":"image","attrs":{"src":"/seed/court-archivist-scene.svg","alt":"촛불 아래 붓과 먹이 놓인 궁궐의 서안"}},{"type":"paragraph","content":[{"type":"text","text":"영화는 왕을 악인으로 그리지 않는다. 자신을 지키려 애쓰는 인간적인 군주이기에, 그를 기록해야 하는 사관의 고민은 충성과 진실 사이에서 더욱 깊어진다."}]},{"type":"image","attrs":{"src":"/seed/court-archivist-scene-2.svg","alt":"눈 내리는 궁궐 마당을 홀로 건너는 관리"}},{"type":"paragraph","content":[{"type":"text","text":"먹을 가는 소리와 종이 넘기는 소리를 살린 음향 설계가 탁월하다. 침묵으로 가득 찬 궁궐에서 붓끝이 종이에 닿는 작은 소리가 천둥처럼 들리는 순간이 있다."}]},{"type":"paragraph","content":[{"type":"text","text":"기록이 곧 권력이던 시대의 이야기는 지금 여기의 질문으로 곧장 이어진다. 묵직한 주제를 설교 없이 전하는, 올해 가장 단단한 사극이다."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"이 글은 포트폴리오를 위해 지어낸 가상의 영화 리뷰입니다."}]}]}'::jsonb, '2026-05-06T09:00:00.000Z', '2026-05-06T09:00:00.000Z'),
  ('sample-ninth-bridge', '아홉 번째 다리', 2024, 4, ARRAY['전쟁', '역사']::text[], '/seed/ninth-bridge-poster.svg', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"후퇴하는 공병대가 강 위의 다리 아홉 개를 차례로 폭파하라는 명령을 받는다. 영화는 전장의 영웅담이 아니라 자기 손으로 길을 끊어야 하는 사람들의 하루를 따라간다."}]},{"type":"image","attrs":{"src":"/seed/ninth-bridge-scene.svg","alt":"포연 속에 절반쯤 무너진 철교"}},{"type":"paragraph","content":[{"type":"text","text":"다리를 건너지 못한 피란민의 행렬이 등장하면서 임무는 잔인한 질문으로 바뀐다. 명령과 양심 사이에서 내리는 결정에 정답이 없다는 것을 영화는 누구도 편들지 않고 보여 준다."}]},{"type":"image","attrs":{"src":"/seed/ninth-bridge-scene-2.svg","alt":"강가 참호에서 건너편을 살피는 병사들의 실루엣"}},{"type":"paragraph","content":[{"type":"text","text":"폭파 장면은 스펙터클로 소비되지 않는다. 다리가 무너진 뒤의 고요와 강물 위로 떠내려가는 잔해가 폭발 자체보다 훨씬 오랫동안 화면을 차지한다."}]},{"type":"paragraph","content":[{"type":"text","text":"다소 많은 등장인물이 후반에 뒤섞이는 것은 아쉽다. 그래도 전쟁을 지도 위의 화살표가 아니라 사람의 무게로 기억하게 만드는 드문 작품이다."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"이 글은 포트폴리오를 위해 지어낸 가상의 영화 리뷰입니다."}]}]}'::jsonb, '2026-04-29T09:00:00.000Z', '2026-04-29T09:00:00.000Z'),
  ('sample-radio-silence', '무전 침묵', 2025, 3, ARRAY['전쟁', '스릴러']::text[], '/seed/radio-silence-poster.svg', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"적진 한가운데 고립된 통신병 세 사람이 무전을 켤 수도 끌 수도 없는 상황에 놓인다. 작은 소리 하나가 곧 죽음이 되는 설정이 초반 한 시간을 숨 막히게 끌고 간다."}]},{"type":"image","attrs":{"src":"/seed/radio-silence-scene.svg","alt":"어두운 벙커 안에서 빛나는 무전기의 다이얼"}},{"type":"paragraph","content":[{"type":"text","text":"거의 대사 없이 눈빛과 손짓으로 진행되는 구간은 연출의 자신감이 돋보인다. 극장의 다른 관객이 음료를 마시는 소리마저 신경 쓰일 만큼 음향을 덜어 냈다."}]},{"type":"image","attrs":{"src":"/seed/radio-silence-scene-2.svg","alt":"눈 덮인 능선 위를 걷는 정찰병 세 사람"}},{"type":"paragraph","content":[{"type":"text","text":"하지만 정체불명의 무전 신호가 내부의 배신자 이야기로 풀리면서 영화는 범작으로 내려앉는다. 설득력이 부족한 반전에 기대기에는 앞선 긴장이 아까웠다."}]},{"type":"paragraph","content":[{"type":"text","text":"연출자의 다음 작품을 기대하게 하는 데뷔작으로 기억해 둘 만하다. 소리를 다루는 감각만큼은 이미 수준급이다."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"이 글은 포트폴리오를 위해 지어낸 가상의 영화 리뷰입니다."}]}]}'::jsonb, '2026-04-22T09:00:00.000Z', '2026-04-22T09:00:00.000Z'),
  ('sample-basement-tenant', '지하의 세입자', 2026, 4, ARRAY['공포', '미스터리']::text[], '/seed/basement-tenant-poster.svg', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"오래된 다세대 주택을 물려받은 주인공이 임대 장부에서 존재하지 않는 지하층의 세입자를 발견한다. 월세는 꼬박꼬박 들어오는데 그 층으로 내려가는 계단이 없다."}]},{"type":"image","attrs":{"src":"/seed/basement-tenant-scene.svg","alt":"지하로 이어지는 좁은 계단과 깜빡이는 전구"}},{"type":"paragraph","content":[{"type":"text","text":"영화는 귀신보다 집이라는 공간을 무섭게 만든다. 벽을 타고 들리는 물소리와 조금씩 달라지는 복도 길이가 쌓이면서 일상의 공간이 믿을 수 없는 곳으로 변해 간다."}]},{"type":"image","attrs":{"src":"/seed/basement-tenant-scene-2.svg","alt":"곰팡이가 번진 벽 앞에 놓인 낡은 의자"}},{"type":"paragraph","content":[{"type":"text","text":"갑작스러운 큰 소리로 놀라게 하는 장면은 거의 없다. 대신 화면 구석에 무언가 있었던 것 같은 찜찜함을 남기고, 관객 스스로 어둠을 살피게 만든다."}]},{"type":"paragraph","content":[{"type":"text","text":"전세 사기와 주거 불안을 건드리는 후반의 진상도 설득력이 있다. 무서운 것은 결국 지하가 아니라 위층 사람들의 무관심이었다는 결론이 서늘하게 남는다."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"이 글은 포트폴리오를 위해 지어낸 가상의 영화 리뷰입니다."}]}]}'::jsonb, '2026-04-15T09:00:00.000Z', '2026-04-15T09:00:00.000Z'),
  ('sample-hollow-school', '빈 학교의 종소리', 2023, 2, ARRAY['공포', '스릴러']::text[], '/seed/hollow-school-poster.svg', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"폐교로 담력 시험을 떠난 대학생들이 사라진다는 이야기는 이미 수없이 보아 온 것이다. 그나마 낡은 종이 혼자 울리는 첫 장면에서 잠시 기대를 품게 된다."}]},{"type":"image","attrs":{"src":"/seed/hollow-school-scene.svg","alt":"먼지 쌓인 책상이 줄지어 놓인 폐교 교실"}},{"type":"paragraph","content":[{"type":"text","text":"그러나 등장인물들은 공포 영화의 모든 잘못된 선택을 빠짐없이 저지른다. 굳이 흩어지고, 굳이 혼자 지하실로 내려가며, 관객은 다음 희생자를 어렵지 않게 맞힌다."}]},{"type":"image","attrs":{"src":"/seed/hollow-school-scene-2.svg","alt":"달빛이 비치는 긴 복도 끝의 낡은 종"}},{"type":"paragraph","content":[{"type":"text","text":"폐교 세트의 분위기만큼은 나쁘지 않다. 먼지 낀 창으로 들어오는 달빛과 삐걱이는 마룻바닥은 더 나은 각본을 만났다면 큰 힘을 발휘했을 것이다."}]},{"type":"paragraph","content":[{"type":"text","text":"결말의 반전은 앞뒤가 맞지 않아 실소를 자아낸다. 장르의 열성 팬이 아니라면 굳이 찾아볼 이유가 없는 작품이다."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"이 글은 포트폴리오를 위해 지어낸 가상의 영화 리뷰입니다."}]}]}'::jsonb, '2026-04-08T09:00:00.000Z', '2026-04-08T09:00:00.000Z'),
  ('sample-last-cassette', '마지막 카세트', 2024, 5, ARRAY['음악', '드라마']::text[], '/seed/last-cassette-poster.svg', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"요양원에 있는 아버지의 유품에서 나온 카세트테이프 한 개가 딸을 낯선 소도시로 이끈다. 테이프에는 아버지가 젊은 시절 만들었던, 끝내 발표되지 않은 노래가 담겨 있다."}]},{"type":"image","attrs":{"src":"/seed/last-cassette-scene.svg","alt":"책상 위에 놓인 라벨 없는 카세트테이프"}},{"type":"paragraph","content":[{"type":"text","text":"극 중 노래들이 정말 좋다는 것이 이 영화의 첫 번째 미덕이다. 시대의 분위기를 흉내 내는 데 그치지 않고, 처음 듣는데도 어디선가 들어 본 듯한 멜로디를 만들어 냈다."}]},{"type":"image","attrs":{"src":"/seed/last-cassette-scene-2.svg","alt":"작은 무대 위 조명 아래에 선 기타 하나"}},{"type":"paragraph","content":[{"type":"text","text":"딸이 아버지의 옛 밴드 동료들을 한 사람씩 찾아가는 구조는 평범하지만 만나는 사람마다 기억하는 아버지가 다르다. 그 조각들이 맞춰질수록 몰랐던 한 사람의 얼굴이 드러난다."}]},{"type":"paragraph","content":[{"type":"text","text":"마지막에 노래가 처음으로 끝까지 흘러나올 때, 영화는 아무 말도 덧붙이지 않는다. 객석의 불이 켜질 때까지 일어서지 못한 관객이 나 혼자만은 아니었다."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"이 글은 포트폴리오를 위해 지어낸 가상의 영화 리뷰입니다."}]}]}'::jsonb, '2026-04-01T09:00:00.000Z', '2026-04-01T09:00:00.000Z'),
  ('sample-brass-street', '금관의 거리', 2025, 4, ARRAY['음악', '코미디']::text[], '/seed/brass-street-poster.svg', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"철거를 앞둔 상가의 상인들이 보상금 협상 대신 금관 악단을 결성한다. 악기를 처음 잡아 본 사람들이 내는 끔찍한 소리가 영화 초반의 가장 큰 웃음거리다."}]},{"type":"image","attrs":{"src":"/seed/brass-street-scene.svg","alt":"낡은 상가 골목에 줄지어 선 금관악기 연주자들"}},{"type":"paragraph","content":[{"type":"text","text":"오합지졸이 성장해 대회에 나간다는 공식을 영화도 잘 알고 있어서, 일부러 그 기대를 비틀며 논다. 대회는 엉뚱한 이유로 취소되고 진짜 무대는 전혀 다른 곳에서 열린다."}]},{"type":"image","attrs":{"src":"/seed/brass-street-scene-2.svg","alt":"악기 수리점 진열창에 비친 트럼펫"}},{"type":"paragraph","content":[{"type":"text","text":"상인 각자의 사정을 짧게나마 챙기는 각본이 영리하다. 세탁소 부부의 말다툼이 합주 속 박자 다툼으로 이어지는 장면은 음악과 코미디가 가장 잘 만난 대목이다."}]},{"type":"paragraph","content":[{"type":"text","text":"철거라는 현실을 너무 낙관적으로 푸는 결말이 걸리기는 한다. 그래도 골목을 가득 채우는 마지막 합주 앞에서 그 불만은 잠시 접어 두게 된다."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"이 글은 포트폴리오를 위해 지어낸 가상의 영화 리뷰입니다."}]}]}'::jsonb, '2026-03-25T09:00:00.000Z', '2026-03-25T09:00:00.000Z'),
  ('sample-lake-disappearance', '호수가 사라진 날', 2026, 4, ARRAY['미스터리', 'SF']::text[], '/seed/lake-disappearance-poster.svg', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"어느 날 아침 작은 마을의 호수가 물 한 방울 남기지 않고 사라진다. 드러난 호수 바닥에서 사십 년 전 실종된 사람들의 물건이 하나둘 발견되며 조용하던 마을이 술렁인다."}]},{"type":"image","attrs":{"src":"/seed/lake-disappearance-scene.svg","alt":"물이 사라져 갈라진 호수 바닥과 좌초한 보트"}},{"type":"paragraph","content":[{"type":"text","text":"수자원 공사에서 파견된 조사관의 건조한 시선이 이야기의 중심을 잡는다. 초자연적인 소재를 다루면서도 수치와 보고서로 접근하는 태도가 오히려 기이함을 또렷하게 만든다."}]},{"type":"image","attrs":{"src":"/seed/lake-disappearance-scene-2.svg","alt":"호수 바닥 한가운데 솟아 있는 이상한 금속 구조물"}},{"type":"paragraph","content":[{"type":"text","text":"마을 사람들은 저마다 호수 바닥을 보여 주고 싶어 하지 않는 이유가 있다. 과학 수수께끼로 시작한 영화는 어느새 공동체가 함께 묻어 둔 비밀의 이야기로 옮겨 간다."}]},{"type":"paragraph","content":[{"type":"text","text":"마지막에 밝혀지는 구조물의 정체는 관객마다 호불호가 갈릴 것이다. 그러나 답보다 질문이 훨씬 오래 남는다는 점에서 이 장르가 할 수 있는 일을 충분히 해낸 작품이다."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"이 글은 포트폴리오를 위해 지어낸 가상의 영화 리뷰입니다."}]}]}'::jsonb, '2026-03-18T09:00:00.000Z', '2026-03-18T09:00:00.000Z'),
  ('sample-sunday-special', '일요일 특집극', 2023, 3, ARRAY['TV 영화', '코미디']::text[], '/seed/sunday-special-poster.svg', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"방송국이 폐국을 앞두고 만드는 마지막 일요일 특집극의 제작 현장을 그린 텔레비전용 영화다. 생방송 사고가 줄줄이 이어지는 구성은 작은 화면에 잘 어울린다."}]},{"type":"image","attrs":{"src":"/seed/sunday-special-scene.svg","alt":"낡은 방송국 스튜디오의 카메라와 조명"}},{"type":"paragraph","content":[{"type":"text","text":"베테랑 조연들이 총출동해 제 몫을 다한다. 대본을 외우지 못한 원로 배우와 그를 어떻게든 살리려는 신입 조연출의 호흡은 극장 영화 못지않은 웃음을 준다."}]},{"type":"image","attrs":{"src":"/seed/sunday-special-scene-2.svg","alt":"조정실 모니터 앞에 모여 앉은 제작진"}},{"type":"paragraph","content":[{"type":"text","text":"텔레비전 예산의 한계는 분명하다. 대부분의 장면이 스튜디오 세트 안에서 벌어지고 조명도 평평하지만, 연극적인 답답함이 소재와 맞아 크게 거슬리지 않는다."}]},{"type":"paragraph","content":[{"type":"text","text":"방송의 전성기를 추억하는 대목은 조금 감상적이다. 일요일 저녁 가족과 함께 틀어 놓기에 알맞은, 딱 그만큼의 소박한 재미가 있다."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"이 글은 포트폴리오를 위해 지어낸 가상의 영화 리뷰입니다."}]}]}'::jsonb, '2026-03-11T09:00:00.000Z', '2026-03-11T09:00:00.000Z'),
  ('sample-night-desk', '심야 보도국', 2024, 4, ARRAY['TV 영화', '드라마', '범죄']::text[], '/seed/night-desk-poster.svg', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"지역 방송국의 심야 뉴스 팀이 경찰 내부 비리 제보를 받는다. 텔레비전용으로 제작되어 규모는 작지만 하룻밤 사이에 벌어지는 이야기라 긴장이 흩어지지 않는다."}]},{"type":"image","attrs":{"src":"/seed/night-desk-scene.svg","alt":"불 켜진 모니터만 남은 한밤의 보도국"}},{"type":"paragraph","content":[{"type":"text","text":"기사를 내보낼지 말지를 두고 벌어지는 회의 장면이 이 작품의 하이라이트다. 큰 소리가 오가지 않아도 저마다의 생계와 신념이 부딪히는 대사가 팽팽하게 이어진다."}]},{"type":"image","attrs":{"src":"/seed/night-desk-scene-2.svg","alt":"비 오는 새벽 방송국 건물 앞의 취재 차량"}},{"type":"paragraph","content":[{"type":"text","text":"화려한 추적 장면 없이 전화 통화와 자료 대조만으로 사건을 밀고 나가는 뚝심이 좋다. 취재라는 일이 실제로 얼마나 지루하고 집요한지 정직하게 보여 준다."}]},{"type":"paragraph","content":[{"type":"text","text":"마지막 뉴스 원고를 읽는 앵커의 얼굴 위로 끝나는 결말은 깔끔하다. 극장에 걸렸어도 손색없었을 잘 만든 소품이다."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"이 글은 포트폴리오를 위해 지어낸 가상의 영화 리뷰입니다."}]}]}'::jsonb, '2026-03-04T09:00:00.000Z', '2026-03-04T09:00:00.000Z'),
  ('sample-wolves-border', '국경의 늑대들', 2026, 3, ARRAY['서부', '스릴러']::text[], '/seed/wolves-border-poster.svg', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"가축 도둑을 쫓던 목장 일꾼들이 국경 너머에서 더 큰 범죄를 발견한다. 고전 서부극의 풍경을 빌려 왔지만 총보다 트럭과 위성 전화가 먼저 등장하는 현대물이다."}]},{"type":"image","attrs":{"src":"/seed/wolves-border-scene.svg","alt":"철조망이 끝없이 이어지는 메마른 평원"}},{"type":"paragraph","content":[{"type":"text","text":"끝없는 평원을 활용한 추격은 시원하다. 숨을 곳 하나 없는 지형에서 멀리 보이는 먼지구름만으로 긴장을 만들어 내는 연출이 특히 인상적이다."}]},{"type":"image","attrs":{"src":"/seed/wolves-border-scene-2.svg","alt":"모닥불 곁에 앉은 사람들 뒤로 어두운 산맥"}},{"type":"paragraph","content":[{"type":"text","text":"반면 일꾼 무리 안에서 배신자를 찾는 이야기는 지나치게 복잡하다. 이름도 잘 기억나지 않는 인물들의 사연이 뒤늦게 쏟아지며 후반의 속도를 떨어뜨린다."}]},{"type":"paragraph","content":[{"type":"text","text":"끝맺음은 허무하지만 풍경과 분위기만으로도 어느 정도 값을 한다. 장르 영화를 좋아한다면 무난하게 즐길 만하다."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"이 글은 포트폴리오를 위해 지어낸 가상의 영화 리뷰입니다."}]}]}'::jsonb, '2026-02-25T09:00:00.000Z', '2026-02-25T09:00:00.000Z');
