-- scripts/generate-seed.mjs로 만든 가상의 리뷰입니다.
-- 처음 16편의 본문을 늘려 글과 이미지를 번갈아 놓고 장르를 더한 뒤, 20편을 새로 넣습니다.
-- 운영자가 이미 고친 글(updated_at이 달라진 글)은 덮어쓰지 않습니다.
UPDATE reviews SET genres = ARRAY['드라마']::text[], body = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"문 닫는 동네 극장의 마지막 밤을 그린 이 영화는 큰 사건 없이도 끝까지 시선을 붙잡는다."}]},{"type":"image","attrs":{"src":"/seed/last-screening-scene.svg","alt":"붉은 노을 아래 지평선 위로 해가 걸린 풍경"}},{"type":"paragraph","content":[{"type":"text","text":"영사기 돌아가는 소리와 객석의 숨소리만으로 쌓아 올린 후반 20분은 올해 본 가장 아름다운 장면이다."}]},{"type":"image","attrs":{"src":"/seed/last-screening-scene-2.svg","alt":"텅 빈 객석 너머로 빛이 새어 나오는 영사실 창"}},{"type":"paragraph","content":[{"type":"text","text":"감독은 극장을 추억의 장소로 미화하지 않는다. 곰팡이 핀 벽지와 밀린 공과금 고지서가 영사기만큼 오래 화면에 머물고, 그 덕분에 이별은 감상이 아니라 생활의 문제가 된다."}]},{"type":"paragraph","content":[{"type":"text","text":"늙은 영사기사를 연기한 배우는 대사보다 손으로 말한다. 필름을 감는 손끝이 조금씩 떨리기 시작하는 장면에서 관객은 이 사람이 무엇을 잃는지 설명 없이 알아차린다."}]},{"type":"paragraph","content":[{"type":"text","text":"극장 문을 나서는 마지막 관객의 뒷모습 위로 조명이 하나씩 꺼질 때, 영화는 슬픔을 강요하지 않고 자리에서 일어날 시간을 조용히 건넨다."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"이 글은 포트폴리오를 위해 지어낸 가상의 영화 리뷰입니다."}]}]}'::jsonb WHERE id = 'sample-last-screening' AND updated_at = created_at;
UPDATE reviews SET genres = ARRAY['드라마', '모험']::text[], body = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"얼어붙은 바다를 건너는 쇄빙선 선원들의 이야기. 느린 호흡이 지루함과 긴장 사이를 아슬아슬하게 오간다."}]},{"type":"image","attrs":{"src":"/seed/winter-route-scene.svg","alt":"차가운 푸른빛 바다 위로 낮은 해가 뜬 풍경"}},{"type":"paragraph","content":[{"type":"text","text":"결말은 호불호가 갈리겠지만, 화면에 담긴 추위만큼은 객석까지 그대로 전해진다."}]},{"type":"image","attrs":{"src":"/seed/winter-route-scene-2.svg","alt":"얼음을 가르며 나아가는 쇄빙선의 어두운 윤곽"}},{"type":"paragraph","content":[{"type":"text","text":"배가 얼음에 갇히는 중반부터 영화는 조난극의 공식을 벗어난다. 구조를 기다리는 긴장보다 좁은 선실에서 서로를 견디는 일이 더 큰 사건이 된다."}]},{"type":"paragraph","content":[{"type":"text","text":"선장과 신입 항해사의 갈등은 끝내 화해로 정리되지 않는다. 그 미완의 관계가 오히려 항해가 끝난 뒤에도 오래 남는 여운을 만든다."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"이 글은 포트폴리오를 위해 지어낸 가상의 영화 리뷰입니다."}]}]}'::jsonb WHERE id = 'sample-winter-route' AND updated_at = created_at;
UPDATE reviews SET genres = ARRAY['스릴러', '범죄']::text[], body = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"비에 젖은 도심을 달리는 추격 장면까지는 근래 스릴러 가운데 가장 날카롭다."}]},{"type":"image","attrs":{"src":"/seed/neon-rain-scene.svg","alt":"보랏빛 비가 내리는 밤거리 풍경"}},{"type":"paragraph","content":[{"type":"text","text":"다만 반전을 설명하는 마지막 10분이 앞서 쌓은 긴장을 스스로 풀어 버린다."}]},{"type":"image","attrs":{"src":"/seed/neon-rain-scene-2.svg","alt":"젖은 도로에 번지는 분홍색 간판 불빛"}},{"type":"paragraph","content":[{"type":"text","text":"조명 설계는 흠잡을 데가 없다. 빗물에 번진 간판 불빛이 인물의 얼굴을 시시각각 다른 사람처럼 바꿔 놓고, 누구도 믿을 수 없다는 이야기의 전제를 화면으로 먼저 말한다."}]},{"type":"paragraph","content":[{"type":"text","text":"주인공이 단서를 하나씩 맞춰 가는 과정이 이렇게 잘 짜여 있었기에 결말의 긴 해설이 더욱 아쉽다. 십 분만 덜어 냈다면 올해의 스릴러로 꼽았을 작품이다."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"이 글은 포트폴리오를 위해 지어낸 가상의 영화 리뷰입니다."}]}]}'::jsonb WHERE id = 'sample-neon-rain' AND updated_at = created_at;
UPDATE reviews SET genres = ARRAY['스릴러', '미스터리']::text[], body = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"야근하는 직원들만 남은 빌딩에서 벌어지는 실종 사건을 다룬다. 공간을 다루는 솜씨가 빼어나다."}]},{"type":"image","attrs":{"src":"/seed/silent-floor-scene.svg","alt":"불 꺼진 사무실 복도 끝의 희미한 불빛"}},{"type":"paragraph","content":[{"type":"text","text":"소리를 덜어낸 연출 덕분에 관객은 어느새 숨을 죽이고 복도 끝을 살피게 된다."}]},{"type":"image","attrs":{"src":"/seed/silent-floor-scene-2.svg","alt":"멈춰 선 엘리베이터 문틈으로 비치는 빛"}},{"type":"paragraph","content":[{"type":"text","text":"카메라는 사무실 칸막이 높이에서 좀처럼 내려오지 않는다. 그 낮은 시선 때문에 익숙한 일터가 언제 무엇이 튀어나올지 모르는 미로로 바뀐다."}]},{"type":"paragraph","content":[{"type":"text","text":"범인을 밝히는 순간보다 동료를 의심하기 시작한 사람들의 표정이 더 무섭다. 실종 사건은 결국 우리가 옆자리 사람을 얼마나 모르는지 묻는 장치였다."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"이 글은 포트폴리오를 위해 지어낸 가상의 영화 리뷰입니다."}]}]}'::jsonb WHERE id = 'sample-silent-floor' AND updated_at = created_at;
UPDATE reviews SET genres = ARRAY['SF', '드라마']::text[], body = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"궤도 정거장에 홀로 남은 관측원의 기록. 거대한 설정보다 한 사람의 고독에 집중한 선택이 빛난다."}]},{"type":"image","attrs":{"src":"/seed/glass-orbit-scene.svg","alt":"행성 위로 떠오르는 푸른 빛"}},{"type":"paragraph","content":[{"type":"text","text":"우주를 비추는 긴 고정 숏은 근래 SF가 잊고 있던 경외감을 되살린다."}]},{"type":"image","attrs":{"src":"/seed/glass-orbit-scene-2.svg","alt":"정거장 창밖으로 둥글게 휘어진 행성의 경계"}},{"type":"paragraph","content":[{"type":"text","text":"주인공은 매일 같은 시각에 관측 기록을 남기고 답이 오지 않는 지구에 안부를 보낸다. 반복되는 일과가 쌓일수록 작은 변화 하나가 어떤 폭발보다 크게 다가온다."}]},{"type":"paragraph","content":[{"type":"text","text":"과학적 설명을 아끼는 대신 영화는 무게와 호흡의 감각을 정확하게 살린다. 커다란 질문을 던지고도 답을 서두르지 않는 태도가 끝까지 품위를 지켜 준다."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"이 글은 포트폴리오를 위해 지어낸 가상의 영화 리뷰입니다."}]}]}'::jsonb WHERE id = 'sample-glass-orbit' AND updated_at = created_at;
UPDATE reviews SET genres = ARRAY['SF', '모험']::text[], body = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"설정은 흥미롭지만 세계관 설명에 러닝타임을 너무 많이 쓴다."}]},{"type":"image","attrs":{"src":"/seed/second-sun-scene.svg","alt":"사막 위로 뜬 두 개의 태양"}},{"type":"paragraph","content":[{"type":"text","text":"그럼에도 황량한 사막을 담은 미술만큼은 큰 화면으로 볼 가치가 있다."}]},{"type":"image","attrs":{"src":"/seed/second-sun-scene-2.svg","alt":"모래 언덕 너머로 길게 늘어선 탐사대의 그림자"}},{"type":"paragraph","content":[{"type":"text","text":"초반 한 시간은 용어와 연표를 외우는 수업에 가깝다. 인물이 왜 움직이는지 알기도 전에 세계의 규칙부터 배워야 하니 몰입이 늦을 수밖에 없다."}]},{"type":"paragraph","content":[{"type":"text","text":"탐사대가 사막으로 나서는 후반부터 비로소 영화가 숨을 쉰다. 설명을 멈추고 풍경을 믿었을 때 이 작품이 얼마나 좋아지는지 알 수 있어 더 안타깝다."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"이 글은 포트폴리오를 위해 지어낸 가상의 영화 리뷰입니다."}]}]}'::jsonb WHERE id = 'sample-second-sun' AND updated_at = created_at;
UPDATE reviews SET genres = ARRAY['로맨스', '드라마']::text[], body = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"편지로만 이어지는 두 사람의 십 년을 담담하게 따라간다."}]},{"type":"image","attrs":{"src":"/seed/spring-letter-scene.svg","alt":"벚꽃이 흩날리는 강변 산책로"}},{"type":"paragraph","content":[{"type":"text","text":"두 배우가 한 화면에 서는 장면은 단 하나뿐인데, 그 한 장면을 위해 모든 시간이 쌓인다."}]},{"type":"image","attrs":{"src":"/seed/spring-letter-scene-2.svg","alt":"책상 위에 쌓인 오래된 편지 봉투 위로 드는 햇살"}},{"type":"paragraph","content":[{"type":"text","text":"편지를 읽는 목소리가 화면 밖에서 들려오는 동안 계절이 몇 번이고 바뀐다. 시간이 흐르는 속도를 이토록 다정하게 다룬 멜로는 오랜만이다."}]},{"type":"paragraph","content":[{"type":"text","text":"오해와 우연에 기대는 대신 영화는 두 사람이 각자의 삶을 꾸려 가는 모습을 충실히 보여 준다. 그래서 마지막 답장 한 줄의 무게가 남다르다."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"이 글은 포트폴리오를 위해 지어낸 가상의 영화 리뷰입니다."}]}]}'::jsonb WHERE id = 'sample-spring-letter' AND updated_at = created_at;
UPDATE reviews SET genres = ARRAY['로맨스', '코미디']::text[], body = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"달콤한 설정에 기대는 순간이 많지만 배우들의 호흡이 그 약점을 대부분 덮는다."}]},{"type":"image","attrs":{"src":"/seed/midnight-bakery-scene.svg","alt":"불 켜진 빵집 창문 너머의 밤거리"}},{"type":"paragraph","content":[{"type":"text","text":"가볍게 즐기기에는 부족함이 없는 소품이다."}]},{"type":"image","attrs":{"src":"/seed/midnight-bakery-scene-2.svg","alt":"김이 오르는 갓 구운 빵이 놓인 진열대"}},{"type":"paragraph","content":[{"type":"text","text":"밤에만 문을 여는 빵집이라는 설정은 예쁘지만 그 이상으로 나아가지 않는다. 손님들의 사연은 한 번씩 스쳐 갈 뿐이고 갈등은 늘 빵 한 조각으로 쉽게 풀린다."}]},{"type":"paragraph","content":[{"type":"text","text":"그래도 반죽을 나누며 말다툼하는 장면의 리듬은 사랑스럽다. 큰 기대 없이 늦은 밤에 틀어 두면 제 몫을 하는 영화다."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"이 글은 포트폴리오를 위해 지어낸 가상의 영화 리뷰입니다."}]}]}'::jsonb WHERE id = 'sample-midnight-bakery' AND updated_at = created_at;
UPDATE reviews SET genres = ARRAY['코미디', '로맨스']::text[], body = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"잘못 배달된 청첩장 한 장에서 시작하는 소동극. 타이밍으로 웃기는 법을 아는 드문 코미디다."}]},{"type":"image","attrs":{"src":"/seed/wrong-wedding-scene.svg","alt":"하객 없는 결혼식장에 놓인 빈 의자들"}},{"type":"paragraph","content":[{"type":"text","text":"중반의 식탁 장면은 혼자 봐도 소리 내어 웃게 된다."}]},{"type":"image","attrs":{"src":"/seed/wrong-wedding-scene-2.svg","alt":"엉뚱한 이름이 적힌 청첩장이 놓인 접수대"}},{"type":"paragraph","content":[{"type":"text","text":"인물 열두 명의 착각이 한 공간에서 맞물리는 구조는 시계처럼 정교하다. 복선으로 놓아둔 사소한 소품들이 후반에 차례로 터질 때의 쾌감이 크다."}]},{"type":"paragraph","content":[{"type":"text","text":"웃음이 다 지나간 자리에 두 사람의 어색한 진심이 남는 결말도 좋다. 소동을 끝까지 소동으로 소비하지 않는 점이 이 영화를 한 단계 올려놓는다."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"이 글은 포트폴리오를 위해 지어낸 가상의 영화 리뷰입니다."}]}]}'::jsonb WHERE id = 'sample-wrong-wedding' AND updated_at = created_at;
UPDATE reviews SET genres = ARRAY['코미디']::text[], body = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"직장 풍자로 시작하지만 같은 농담을 반복하다 힘을 잃는다."}]},{"type":"image","attrs":{"src":"/seed/office-picnic-scene.svg","alt":"회의실에 펼쳐 놓은 돗자리"}},{"type":"paragraph","content":[{"type":"text","text":"조연들의 즉흥 연기가 아니었다면 끝까지 보기 어려웠을 것이다."}]},{"type":"image","attrs":{"src":"/seed/office-picnic-scene-2.svg","alt":"사무실 복도를 줄지어 걷는 직원들의 뒷모습"}},{"type":"paragraph","content":[{"type":"text","text":"상사의 말버릇을 비꼬는 농담은 처음 두 번까지 통한다. 그러나 영화는 같은 설정을 다섯 번 더 꺼내고, 그사이 인물들은 조금도 변하지 않는다."}]},{"type":"paragraph","content":[{"type":"text","text":"직장 생활의 피로를 정말로 건드릴 수 있었던 회식 장면마저 슬랩스틱으로 넘겨 버린다. 소재가 아까운 작품이다."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"이 글은 포트폴리오를 위해 지어낸 가상의 영화 리뷰입니다."}]}]}'::jsonb WHERE id = 'sample-office-picnic' AND updated_at = created_at;
UPDATE reviews SET genres = ARRAY['액션', '범죄']::text[], body = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"컨테이너 부두 한 곳에서 90분을 버티는 액션. 합을 끊지 않는 촬영이 체력의 한계까지 보여 준다."}]},{"type":"image","attrs":{"src":"/seed/iron-harbor-scene.svg","alt":"화물 컨테이너가 쌓인 항구의 해질녘"}},{"type":"paragraph","content":[{"type":"text","text":"서사는 단순하지만 몸으로 쓴 장면들이 그 단순함을 오히려 장점으로 만든다."}]},{"type":"image","attrs":{"src":"/seed/iron-harbor-scene-2.svg","alt":"크레인 아래 어둠 속에 쌓인 녹슨 컨테이너"}},{"type":"paragraph","content":[{"type":"text","text":"주인공은 싸울수록 느려지고 숨이 가빠진다. 영웅의 지치지 않는 몸 대신 고통이 누적되는 몸을 보여 주는 선택이 액션의 긴장을 끝까지 유지한다."}]},{"type":"paragraph","content":[{"type":"text","text":"좁은 통로와 층층이 쌓인 철판을 이용한 동선은 공간 활용의 교본이라 할 만하다. 장르 팬이라면 극장에서 볼 이유가 충분하다."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"이 글은 포트폴리오를 위해 지어낸 가상의 영화 리뷰입니다."}]}]}'::jsonb WHERE id = 'sample-iron-harbor' AND updated_at = created_at;
UPDATE reviews SET genres = ARRAY['액션', '스릴러']::text[], body = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"달리는 열차라는 익숙한 무대를 성실하게 활용한다. 새롭지는 않아도 지루할 틈은 없다."}]},{"type":"image","attrs":{"src":"/seed/night-express-scene.svg","alt":"어둠 속을 달리는 열차의 창문 불빛"}},{"type":"paragraph","content":[{"type":"text","text":"후반의 객차 분리 장면은 충분히 기억할 만하다."}]},{"type":"image","attrs":{"src":"/seed/night-express-scene-2.svg","alt":"터널 입구로 빨려 들어가는 열차의 불빛"}},{"type":"paragraph","content":[{"type":"text","text":"여러 칸을 오가는 추격전은 앞선 열차 영화들을 부지런히 복습한다. 익숙한 공식이지만 편집의 리듬이 흐트러지지 않아 보는 동안 불만을 느낄 새가 없다."}]},{"type":"paragraph","content":[{"type":"text","text":"악역의 동기가 끝내 납작한 것은 아쉽다. 그래도 주말 저녁 두 시간의 값은 정직하게 치르는 오락 영화다."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"이 글은 포트폴리오를 위해 지어낸 가상의 영화 리뷰입니다."}]}]}'::jsonb WHERE id = 'sample-night-express' AND updated_at = created_at;
UPDATE reviews SET genres = ARRAY['다큐멘터리']::text[], body = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"사라져 가는 염전의 한 해를 내레이션 없이 기록한다. 인내심 있는 카메라가 노동의 리듬을 그대로 옮긴다."}]},{"type":"image","attrs":{"src":"/seed/salt-makers-scene.svg","alt":"해 질 무렵 염전에 비친 하늘"}},{"type":"paragraph","content":[{"type":"text","text":"마지막 수확 장면에 이르면 소금 한 줌의 무게가 다르게 느껴진다."}]},{"type":"image","attrs":{"src":"/seed/salt-makers-scene-2.svg","alt":"염전 위에 소복이 쌓인 하얀 소금 더미"}},{"type":"paragraph","content":[{"type":"text","text":"감독은 삼 년 동안 한 마을에 머물며 인물들이 카메라를 잊을 때까지 기다렸다. 그렇게 얻은 일상의 대화들이 어떤 인터뷰보다 많은 것을 알려 준다."}]},{"type":"paragraph","content":[{"type":"text","text":"염전이 왜 사라지는지 영화는 직접 주장하지 않는다. 비어 가는 염전과 늙어 가는 손을 차례로 보여 줄 뿐인데, 그 침묵이 어떤 내레이션보다 단호하다."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"이 글은 포트폴리오를 위해 지어낸 가상의 영화 리뷰입니다."}]}]}'::jsonb WHERE id = 'sample-salt-makers' AND updated_at = created_at;
UPDATE reviews SET genres = ARRAY['다큐멘터리']::text[], body = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"도심 비둘기와 함께 사는 사람들을 따라간다. 소재의 재미에 비해 구성은 다소 느슨하다."}]},{"type":"image","attrs":{"src":"/seed/city-of-pigeons-scene.svg","alt":"광장 위를 나는 비둘기 떼"}},{"type":"paragraph","content":[{"type":"text","text":"그래도 노년의 사육사가 전하는 이야기만큼은 오래 남는다."}]},{"type":"image","attrs":{"src":"/seed/city-of-pigeons-scene-2.svg","alt":"옥상 비둘기 집 앞에 앉은 노인의 실루엣"}},{"type":"paragraph","content":[{"type":"text","text":"비둘기를 유해 동물로 보는 쪽과 이웃으로 여기는 쪽을 번갈아 보여 주지만, 양쪽 입장을 나열하는 데 그쳐 논의가 깊어지지 않는다."}]},{"type":"paragraph","content":[{"type":"text","text":"옥상에서 새를 날려 보내는 노인의 손짓을 담은 마지막 장면은 그래서 더 돋보인다. 이 장면에 집중한 단편이었다면 더 좋았을 것이다."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"이 글은 포트폴리오를 위해 지어낸 가상의 영화 리뷰입니다."}]}]}'::jsonb WHERE id = 'sample-city-of-pigeons' AND updated_at = created_at;
UPDATE reviews SET genres = ARRAY['애니메이션', '가족', '판타지']::text[], body = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"손으로 접은 종이의 질감을 그대로 살린 화면이 시작부터 눈을 사로잡는다."}]},{"type":"image","attrs":{"src":"/seed/paper-whale-scene.svg","alt":"종이로 접은 고래가 헤엄치는 밤하늘"}},{"type":"paragraph","content":[{"type":"text","text":"어린 관객을 얕보지 않는 이야기 덕분에 어른에게 더 깊게 남는다."}]},{"type":"image","attrs":{"src":"/seed/paper-whale-scene-2.svg","alt":"접힌 종이 파도를 넘는 작은 배"}},{"type":"paragraph","content":[{"type":"text","text":"주름과 접힌 자국이 그대로 남은 캐릭터들은 움직일 때마다 바스락거리는 소리를 낸다. 시각과 청각을 함께 설계한 세심함이 작품 전체의 세계를 믿게 만든다."}]},{"type":"paragraph","content":[{"type":"text","text":"고래를 떠나보내는 결말은 어린이 영화의 관습적인 위로를 택하지 않는다. 슬픔을 슬픔으로 남겨 두는 용기 덕분에 오래 기억될 작품이 되었다."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"이 글은 포트폴리오를 위해 지어낸 가상의 영화 리뷰입니다."}]}]}'::jsonb WHERE id = 'sample-paper-whale' AND updated_at = created_at;
UPDATE reviews SET genres = ARRAY['애니메이션', '가족', '모험']::text[], body = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"바닷가 마을의 등대를 지키는 아이의 모험. 단순한 그림체가 오히려 감정을 또렷하게 전한다."}]},{"type":"image","attrs":{"src":"/seed/little-lighthouse-scene.svg","alt":"파도 위로 빛을 비추는 작은 등대"}},{"type":"paragraph","content":[{"type":"text","text":"음악과 파도 소리의 조화가 특히 좋다."}]},{"type":"image","attrs":{"src":"/seed/little-lighthouse-scene-2.svg","alt":"폭풍우 속에서 빛나는 등대의 창"}},{"type":"paragraph","content":[{"type":"text","text":"폭풍우 장면은 큰 소리로 겁을 주지 않는다. 등불 하나를 지키려는 아이의 작은 몸짓을 따라가며 어린 관객도 감당할 수 있는 긴장을 정성껏 쌓는다."}]},{"type":"paragraph","content":[{"type":"text","text":"마을 어른들이 하나둘 등대로 올라오는 후반은 예상대로 흘러가도 뭉클하다. 온 가족이 함께 보기에 이만한 작품을 찾기 어렵다."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"이 글은 포트폴리오를 위해 지어낸 가상의 영화 리뷰입니다."}]}]}'::jsonb WHERE id = 'sample-little-lighthouse' AND updated_at = created_at;

